WITH cleaned AS (SELECT *, CONCAT_WS('-', carrier, status) AS carrier_status_key, ROUND(DATEDIFF(delivered_date, shipped_date) / 30, 1) AS months_shipped_date_to_delivered_date, COALESCE(carrier, 'UNKNOWN') AS carrier_clean FROM shipments WHERE shipped_date >= DATE '2023-07-31') SELECT id, carrier, shipped_date, delivered_date, carrier_status_key, SUM(months_shipped_date_to_delivered_date) OVER w_recent AS last7_sum_months_shipped_date_to_delivered_date, MIN(months_shipped_date_to_delivered_date) OVER w_recent AS last7_min_months_shipped_date_to_delivered_date, AVG(months_shipped_date_to_delivered_date) OVER w_recent AS last7_avg_months_shipped_date_to_delivered_date, MAX(months_shipped_date_to_delivered_date) OVER w_recent AS last7_max_months_shipped_date_to_delivered_date FROM cleaned WHERE MONTH(delivered_date) IN (7, 11, 12) WINDOW w_recent AS (PARTITION BY order_id, carrier ORDER BY months_shipped_date_to_delivered_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)
